import * as E from './engine.js?v=missions12';
import {jobs,mountPuzzle} from './practical.js?v=missions12';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let screenKey='',state=null,view='work',step=0,scene=null,sceneLib=null,sceneToken=0,paused=false,toastTimer;const key='devlife-v2',modal=$('#modal'),content=$('#dialog-content');
let practicalCleanup=null;modal.addEventListener('close',()=>{practicalCleanup?.();practicalCleanup=null;});
const fmt=n=>Math.round(n).toLocaleString('ru-RU');
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function save(){if(!state)return;state.log=state.log.slice(0,100);try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Автосохранение недоступно. Скачай прогресс кнопкой «Сохранить».');}}
function run(fn,{redraw=true}={}){try{fn();save();if(redraw)render();}catch(e){toast(e.message);}}
function header(){return `<header><a class="logo" href="./">dev<span>life</span><i>▧</i></a><span class="header-note">НАЙДИ СВОЮ РОЛЬ В IT</span><div class="header-actions"><a href="presentation.html" target="_blank">Презентация v2 (архив) ↗</a><button class="plain" id="help">Как играть</button>${state?'<button class="plain" id="save">Сохранить ↓</button>':''}</div></header>`;}
function footer(){return '<div class="footer"><span>Учебный симулятор. CR — игровые деньги. Все покупки и найм происходят только в игре.</span><span>Локальная версия · без регистрации</span></div>';}
function open(html,locked=false){content.innerHTML=`<div class="dialog-top"><span class="kicker">DEVLIFE / ${state?esc(E.role(state).name):'КАРЬЕРА'}</span>${locked?'':'<button class="close" aria-label="Закрыть">×</button>'}</div>`+html;modal.dataset.locked=locked?'1':'0';if(!modal.open)modal.showModal();$('.close')?.addEventListener('click',()=>modal.close());}
modal.addEventListener('cancel',e=>{if(modal.dataset.locked==='1')e.preventDefault();});
function attachScene(mode){const token=++sceneToken;scene?.dispose();scene=null;const canvas=$('#world');if(!canvas)return;const launch=lib=>{if(token!==sceneToken||!canvas.isConnected)return;try{scene=mode==='office'?lib.createStudio(canvas,{staff:state.company?.staff.length||0,inventory:state.inventory}):lib.createProcess(canvas,state?E.role(state):E.ROLES[0],step,state?.stage==='boss');}catch{$('#scene-note').textContent='3D недоступно на этом устройстве. Все объяснения и задания доступны текстом.';}};if(sceneLib)launch(sceneLib);else import('./scene.js').then(lib=>{sceneLib=lib;launch(lib);}).catch(()=>{if($('#scene-note'))$('#scene-note').textContent='3D не загрузилось. Игру можно пройти по текстовым объяснениям.';});}
function bindHeader(){$('#help').onclick=help;if($('#save'))$('#save').onclick=()=>{save();download();};}
function render(){if(state&&state.stage!=='career'){location.href='./';return;}const nextScreen=state?[state.stage,state.quizIndex,state.bossIndex,view].join(':'):'home';if(nextScreen!==screenKey){window.scrollTo(0,0);screenKey=nextScreen;}sceneToken++;scene?.dispose();scene=null;$('#app').innerHTML=header()+'<main>'+(!state?home():state.stage==='career'?career():onboarding())+footer()+'</main>';bindHeader();if(!state)bindHome();else if(state.stage==='career')bindCareer();else bindOnboarding();if(state?.pending&&!modal.open)eventDialog();}
function home(){return `<section class="hero"><div><span class="kicker">ТРИ ПРОФЕССИИ. ТВОЙ МАРШРУТ.</span><h1>Кем ты будешь<br><em>в мире IT?</em></h1><p>Попробуй профессию в деле. Пройди босса. Вырасти до своей компании.</p></div><div class="hero-side">Короткое знакомство, понятные решения и студия, которая развивается вместе с тобой.</div></section><div class="path"><span><b>01</b> Выбери роль</span><span><b>02</b> Практика в профессии</span><span><b>03</b> Босс на 2 минуты</span><span><b>04</b> Карьера и компания</span></div><div class="form-row"><label class="field">Как тебя называть<input id="nickname" maxlength="22" placeholder="Твой никнейм" value="Даниил"></label><label class="field">Режим<select id="mode"><option value="easy">Знакомство · босс 150 сек</option><option value="normal" selected>Карьера · босс 120 сек</option><option value="hard">Вызов · босс 90 сек</option></select></label></div><section class="roles">${E.ROLES.map(r=>`<article class="role-card"><div class="role-icon">${r.icon}</div><h2>${r.name}</h2><p>${r.description}</p><span class="mini">${r.flow}</span><button class="btn" data-role="${r.id}">Попробовать профессию ↗</button></article>`).join('')}</section><div class="welcome-foot"><p class="mini">Сначала знакомство с профессией, затем настоящая игровая карьера.<br>Прогресс сохраняется автоматически. Старое сохранение DevLife v1 остаётся нетронутым.</p><div class="row"><button class="btn secondary" id="continue">Продолжить игру</button><button class="btn secondary" id="load">Загрузить сохранение</button></div></div>`;}
function bindHome(){document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>run(()=>{const name=$('#nickname').value,mode=$('#mode').value;location.href='./';}));$('#continue').onclick=()=>run(()=>{const raw=localStorage.getItem(key);if(!raw)throw Error('Сохранения новой версии пока нет. Выбери профессию.');state=E.restore(raw);});$('#load').onclick=()=>$('#import').click();}
function rail(){return `<div class="rail"><span class="${state.stage==='quiz'?'active':''}">01 Знакомство</span><span class="${state.stage.startsWith('boss')?'active':''}">02 Главный босс</span><span>03 Карьера</span><span>04 Компания</span></div>`;}
function process(){const r=E.role(state);return `<section class="process-panel"><div class="process-top"><span>КАК РАБОТАЕТ ${esc(r.name.toUpperCase())}</span><span>3D / ${step+1}</span></div><canvas id="world" aria-label="Трёхмерная схема: ${esc(r.flow)}"></canvas><div class="process-labels">${r.labels.map((x,i)=>`<span>${i+1}. ${esc(x)}</span>`).join('')}</div><div class="process-copy"><div class="steps">${r.steps.map((_,i)=>`<button class="step-btn ${i===step?'active':''}" data-step="${i}">Шаг ${i+1}</button>`).join('')}</div><h3>${esc(r.labels[step])}</h3><p>${esc(r.steps[step])}</p><div class="mini" id="scene-note">Светящаяся точка показывает движение сигнала между этапами. Нажми шаг, чтобы разобрать процесс.</div></div></section>`;}
function options(q,feedback=null,wrong=[]){return `<div class="options">${q.options.map((x,i)=>`<button class="option" data-answer="${i}" ${feedback?.correct||state.stage==='quiz'&&feedback||wrong.includes(i)?'disabled':''}><span>${String(i+1).padStart(2,'0')}</span>${esc(x)}</button>`).join('')}</div>`;}
function feedback(f){return f?`<div class="feedback ${f.correct?'':'bad'}"><strong>${f.correct?'Верно. Вот почему.':'Разберём ошибку.'}</strong>${esc(f.why)}</div>`:'';}
function onboarding(){const r=E.role(state);let right;if(state.stage==='quiz'){const q=E.quizQuestion(state);right=`<section class="question"><span class="kicker">ЗНАКОМСТВО · ВОПРОС ${state.quizIndex+1} / 4</span><h2>${esc(q.prompt)}</h2>${options(q,state.quizFeedback)}${feedback(state.quizFeedback)}${state.quizFeedback?'<button class="btn" id="next-quiz">'+(state.quizIndex===3?'Перейти к боссу →':'Следующий вопрос →')+'</button>':'<p class="mini">Выбери один ответ. Ошибка не закрывает профессию: сначала разберём принцип.</p>'}</section>`;}else if(['bossReady','bossFailed'].includes(state.stage)){right=`<section class="boss"><span class="kicker">${state.stage==='bossFailed'?'ЕЩЁ ОДНА ПОПЫТКА':'ФИНАЛЬНОЕ ИСПЫТАНИЕ'}</span><h2>${state.stage==='bossFailed'?'Инцидент ещё<br>не закрыт.':'Босс:<br>аварийный релиз.'}</h2><p>${state.stage==='bossFailed'?'Закончилось время или запас ошибок. Можно начать заново без потери обучения.':'Три решения по твоей специальности. Закрой инцидент, чтобы получить первую работу.'}</p><div class="boss-bar"><span><b>${E.MODES[state.mode].boss}</b> секунд</span><span><b>3</b> жизни</span><span><b>3</b> этапа</span></div><p>Правильный ответ открывает следующий этап. Ошибка отнимает жизнь. Время идёт и во время чтения разбора; при скрытой вкладке оно останавливается.</p><button class="btn" id="start-boss">${state.stage==='bossFailed'?'Повторить испытание':'Я готов. Начать босса'} ↗</button><p class="mini">После победы: +100 CR, +40 XP и доступ к студии.</p></section>`;}else{const q=E.bossQuestion(state);right=`<section class="boss"><span class="kicker">БОСС · ЭТАП ${state.bossIndex+1} / 3</span><div class="boss-bar"><span><b id="boss-time">${Math.ceil(state.bossRemaining)}</b> сек</span><span><b>${'♥'.repeat(state.bossHp)}</b></span></div><h2 style="font-size:27px">${esc(q.prompt.replace('БОСС: ',''))}</h2>${options(q,state.bossFeedback,state.bossWrong)}${feedback(state.bossFeedback)}${state.bossFeedback?.correct?'<button class="btn" id="next-boss">'+(state.bossIndex===2?'Открыть карьеру →':'Следующий этап →')+'</button>':'<p class="mini">Выбери решение. Неверный вариант больше не доступен.</p>'}</section>`;}
return rail()+`<section class="hero"><div><span class="kicker">${esc(r.name)}</span><h1>${state.stage==='quiz'?'Сначала попробуй.<br><em>Потом выбирай.</em>':'Твой первый<br><em>серьёзный вызов.</em>'}</h1></div><button class="plain" id="change-role">← Выбрать другую профессию</button></section><div class="learning">${process()}${right}</div>`;}
function bindOnboarding(){attachScene('process');document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;render();});$('#change-role').onclick=newGame;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>run(()=>{if(state.stage==='quiz')E.answerQuiz(state,+b.dataset.answer);else E.answerBoss(state,+b.dataset.answer);}));if($('#next-quiz'))$('#next-quiz').onclick=()=>run(()=>E.nextQuiz(state));if($('#start-boss'))$('#start-boss').onclick=()=>run(()=>E.startBoss(state));if($('#next-boss'))$('#next-boss').onclick=()=>run(()=>{E.nextBoss(state);if(state.stage==='career'){view='work';toast('Босс побеждён! Теперь ты Junior. Начни с задачи дня.');}});}
function stats(){return `<div class="stats">${[['money','Бюджет',' CR',5000],['xp','Опыт',' XP',1050],['focus','Фокус','%',100],['stress','Стресс','%',100],['reputation','Репутация','%',100]].map(([k,name,u,max])=>`<div class="stat"><small>${name}</small><strong>${fmt(state[k])}<small style="display:inline;margin-left:5px">${u}</small></strong><div class="bar"><i style="width:${Math.min(100,state[k]/max*100)}%;${k==='stress'?'background:#c4a19a':''}"></i></div></div>`).join('')}</div>`;}
function career(){const r=E.role(state),rn=E.rank(state);return `<section class="hero"><div><span class="kicker">${esc(r.name)} / ДЕНЬ ${state.day}</span><h1>${state.company?esc(state.company.name):'Твоя карьера.<br><em>Твои решения.</em>'}</h1><p>${esc(state.name)} · ${E.RANKS[rn].name} · ${state.company?'Владелец компании':esc(r.company)}</p></div><div class="hero-side">${rn<4?`До ${E.RANKS[rn+1].name}: ещё ${E.RANKS[rn+1].xp-state.xp} XP`:'Тимлид: доступен выкуп компании'}<br>${state.company?`Команда: ${state.company.staff.length} / ${state.company.level*2} мест`:'Работай, учись и собирай капитал.'}</div></section>${stats()}<nav class="tabs">${[['work','Рабочий день'],['shop','Магазин'],['career','Карьера'],['company','Моя компания'],['top','Рейтинг'],['log','Журнал']].map(([id,name])=>`<button class="tab ${view===id?'active':''}" data-view="${id}">${name}</button>`).join('')}</nav>${({work:workView,shop:shopView,career:rankView,company:companyView,top:topView,log:logView})[view]()}<div class="footer"><span>AI Director: локальные правила · события зависят от ресурсов</span><button class="plain" id="pause">${paused?'▶ Продолжить время':'Ⅱ Пауза событий'}</button><button class="plain" id="new">Сменить профессию / новая игра</button></div>`;}
function workView(){const q=E.task(state),next=E.RANKS[E.rank(state)+1],cost=E.MODES[state.mode].cost+E.payroll(state);return `${state.finished?'<div class="completion"><span class="kicker">ГЛАВА ПРОЙДЕНА</span><h2>Ты построил свою IT-компанию.</h2><p>Шесть сотрудников, расширенный офис и три выполненных контракта. Продолжай развивать бизнес или попробуй другую профессию.</p></div>':''}<div class="career-grid"><section class="studio"><span class="studio-label"><span>${esc(E.role(state).company.toUpperCase())}</span><span>ДЕНЬ ${state.day}</span></span><canvas id="world" aria-label="Трёхмерный офис с купленными предметами и сотрудниками"></canvas><div class="studio-foot"><b>${state.company?state.company.staff.length+' сотрудников':'Твоё рабочее место'}</b><span id="scene-note">Потяни мышью, чтобы осмотреть офис</span></div></section><section class="panel"><span class="kicker">${state.taskDone?'✓ ЗАДАЧА ПРИНЯТА':'ОБЯЗАТЕЛЬНАЯ ЗАДАЧА ДНЯ'}</span><h2>${state.taskDone?'Хорошая работа.':q.title}</h2><p>${state.taskDone?'Задание выполнено. Можно заняться развитием или закончить день.':esc(q.context)}</p><p>${state.taskDone?'Каждые семь дней команда выпускает релиз и получает бонус.':esc(jobs[state.role].hint)}</p><div class="reward">${state.taskDone?'+100 очков за выполненную задачу':`+${q.reward} CR · +${q.xp} XP · −${state.inventory.includes('automation')?10:18} фокуса`}</div><button class="btn" id="work-task" ${state.taskDone?'disabled':''}>${state.taskDone?'Уже выполнено':'Решить задачу →'}</button>${state.lastTask?feedback(state.lastTask):''}<div class="progress-title"><span>${next?'Следующий ранг: '+next.name:'Максимальный ранг достигнут'}</span><span>${next?state.xp+' / '+next.xp+' XP':'ТИМЛИД'}</span></div><div class="bar"><i style="width:${next?Math.min(100,state.xp/next.xp*100):100}%"></i></div></section></div><div class="section-head"><h2>Выбери, как провести время</h2><span class="mini">Осталось ${2-state.actions} из 2 действий</span></div><div class="actions">${E.actions(state).map(a=>`<article class="action-card"><h3>${a.name}</h3><p>${a.description}</p><button class="btn secondary" data-action="${a.id}" ${state.actions>=2?'disabled':''}>${a.id==='rest'?'Отдохнуть':a.id==='learn'?'Начать практику':a.id==='talk'?'Обсудить задачу':'Выполнить заказ'}</button></article>`).join('')}</div><div class="day-end"><div><h3>Завершить рабочий день</h3><p>Расходы: ${cost} CR (${E.MODES[state.mode].cost} личные + ${E.payroll(state)} зарплаты).<br>Завтра: +30 фокуса, −${state.inventory.includes('plant')?13:10} стресса и два новых действия.</p></div><button class="btn dark" id="end-day" ${state.taskDone?'':'disabled'}>${state.taskDone?'Завершить день →':'Сначала реши задачу дня'}</button></div><button class="plain" id="recover">Не хватает сил? Внеплановая пауза: +35 фокуса, −20 стресса, −2 репутации</button>`;}
function shopView(){return `<div class="section-head"><div><span class="kicker">ИНВЕСТИЦИИ В РАБОЧЕЕ МЕСТО</span><h2>Вещи, которые помогают работать</h2></div><span class="mini">Баланс ${fmt(state.money)} CR</span></div><div class="shop-grid">${E.shop(state).map((i,n)=>{const owned=state.inventory.includes(i.id),locked=E.rank(state)<i.rank,poor=state.money<i.price;return `<article class="shop-item"><div class="item-icon">${['◫','♧','▣','⌘','⚙'][n]}</div><span class="kicker">${E.RANKS[i.rank].name}</span><h2>${i.name}</h2><p>${i.description}</p><strong>${fmt(i.price)} CR</strong><button class="btn" data-buy="${i.id}" ${owned||locked||poor?'disabled':''}>${owned?'✓ Уже установлено':locked?'Откроется: '+E.RANKS[i.rank].name:poor?'Не хватает '+fmt(i.price-state.money)+' CR':'Купить за '+fmt(i.price)+' CR'}</button></article>`;}).join('')}</div>`;}
function rankView(){return `<span class="kicker">ПРОФЕССИОНАЛЬНЫЙ РОСТ</span><h2>От первой задачи до своей команды</h2><div class="rank-track">${E.RANKS.map((r,i)=>`<div class="rank-node ${E.rank(state)>=i?'active':''}"><strong>${r.name}</strong><small>${r.xp} XP · ${E.rank(state)>=i?'достигнут':'впереди'}</small></div>`).join('')}</div><div class="company-grid"><section class="panel"><h2>Что открывает рост</h2><p><b>Junior:</b> задачи и базовые покупки.<br><b>Middle:</b> второй монитор и выше оплата задач.<br><b>Senior:</b> профессиональное оборудование.<br><b>Senior+:</b> автоматизация и ревью коллег.<br><b>Тимлид:</b> право выкупить компанию за 3 800 CR.</p></section><section class="panel"><h2>Как заработать XP</h2><p>Верное решение рабочей задачи: 75 XP. Второй экран добавляет 15 XP. Практика: ещё 20 XP за действие.</p><p>Повышение происходит автоматически. Раз в семь дней выходит релиз: +200 CR и +150 очков.</p><div class="metrics"><div><b>${state.workCount}</b><span>задач решено</span></div><div><b>${state.releaseCount}</b><span>релизов</span></div><div><b>${fmt(state.score)}</b><span>очков</span></div></div></section></div>`;}
function companyView(){const c=state.company;if(!c){const locked=E.rank(state)<4,poor=state.money<3800;return `<div class="company-grid"><section class="panel"><span class="kicker">СЛЕДУЮЩАЯ ГЛАВА</span><h2>Выкупи компанию.<br>Собери свою команду.</h2><p>После выкупа станут доступны найм, зарплаты, командные контракты и расширение офиса с 2 до 6 мест.</p><label class="field">Название компании<input id="company-name" maxlength="28" value="${esc(E.role(state).company)}"></label><div class="reward">ВЫКУП: 3 800 CR · НУЖЕН РАНГ ТИМЛИД</div><button class="btn" id="acquire" ${locked||poor?'disabled':''}>${locked?'Доступно после 1 050 XP':poor?'Нужно ещё '+fmt(3800-state.money)+' CR':'Выкупить за 3 800 CR'}</button></section><section class="panel"><h2>Владелец отвечает за экономику</h2><p>Найм имеет разовую стоимость. В конце каждого дня нужно платить зарплату всем сотрудникам.</p><p>Один командный контракт в день приносит 400 CR + 100 CR за каждого сотрудника. Для выполнения требуется хотя бы один сотрудник и верное профессиональное решение.</p><p>Финал главы: офис на шесть мест, шесть сотрудников и не менее трёх контрактов.</p><div class="notice">Пока компания не твоя, нанимать людей и расширять офис нельзя.</div></section></div>`;}
return `<div class="company-grid"><section class="panel"><span class="kicker">ТВОЯ КОМПАНИЯ</span><h2>${esc(c.name)}</h2><div class="metrics"><div><b>${c.staff.length}/${c.level*2}</b><span>сотрудники / места</span></div><div><b>${E.payroll(state)}</b><span>зарплаты CR/день</span></div><div><b>${c.contracts}</b><span>контрактов</span></div></div><p>Уровень офиса ${c.level}/3. Расширение добавляет два места. Люди появляются в 3D-студии после найма.</p><button id="expand" class="btn secondary" ${c.level===3||state.money<c.level*1000?'disabled':''}>${c.level===3?'Офис полностью расширен':'Добавить 2 места за '+fmt(c.level*1000)+' CR'}</button></section><section class="panel"><span class="kicker">ДОХОД КОМПАНИИ</span><h2>Командный контракт</h2><p>Твоя команда готовит решение для клиента. Ты выбираешь подход и отвечаешь за результат.</p><div class="reward">+${400+c.staff.length*100} CR · ОДИН КОНТРАКТ В ДЕНЬ</div><button class="btn" id="contract" ${c.contractDone||!c.staff.length?'disabled':''}>${c.contractDone?'Сегодня уже выполнен':!c.staff.length?'Сначала найми сотрудника':'Открыть контракт →'}</button><button class="plain" id="advance">Не хватает на зарплаты? Условия аванса</button></section></div><div class="section-head"><h2>Люди, с которыми растёт бизнес</h2><span class="mini">Кандидаты — игровые персонажи</span></div><div class="staff-grid">${E.CANDIDATES.map(e=>{const hired=c.staff.some(x=>x.id===e.id),full=c.staff.length>=c.level*2,poor=state.money<e.fee;return `<article class="staff"><div class="face">${e.name[0]}</div><h3>${e.name}</h3><span class="kicker">${E.ROLES.find(r=>r.id===e.role).name}</span><p>Найм ${e.fee} CR один раз.<br>Зарплата ${e.salary} CR каждый день.</p><button class="btn ${hired?'secondary':''}" data-hire="${e.id}" ${hired||full||poor?'disabled':''}>${hired?'✓ В твоей команде':full?'Нет свободных мест':poor?'Не хватает денег':'Нанять за '+e.fee+' CR'}</button></article>`;}).join('')}</div>`;}
function topView(){return `<span class="kicker">ЛОКАЛЬНАЯ ЛИГА</span><h2>Твой путь среди специалистов</h2><p>Соперники ниже — виртуальные персонажи. Это демонстрация рейтинга, а не онлайн-таблица реальных игроков.</p><div class="table-wrap"><table><thead><tr><th>Место</th><th>Игрок</th><th>Специальность</th><th>Очки</th><th>Деньги</th><th>Сотрудники</th></tr></thead><tbody>${E.leaderboard(state).map((p,i)=>`<tr class="${p.you?'you':''}"><td>${String(i+1).padStart(2,'0')}</td><td>${esc(p.name)} ${p.you?'(ты)':'· NPC'}</td><td>${p.profession}</td><td>${fmt(p.score)}</td><td>${fmt(p.money)} CR</td><td>${p.employees}</td></tr>`).join('')}</tbody></table></div><div class="notice">Очки: босс +100, задача +100, релиз +150, выкуп +800, найм +250, расширение +300, контракт +200. Аванс уменьшает результат на 100 очков.</div>`;}
function logView(){return '<h2>История твоих решений</h2><p>Здесь видно, что изменилось и почему.</p>'+state.log.map(x=>'<div class="log">'+esc(x)+'</div>').join('');}
function bindCareer(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('#new').onclick=newGame;$('#pause').onclick=()=>{paused=!paused;render();toast(paused?'События на паузе. Можно спокойно изучить интерфейс.':'События снова активны.');};if(view==='work'){attachScene('office');$('#work-task').onclick=taskDialog;$('#end-day').onclick=()=>run(()=>{E.endDay(state);toast('День завершён. Расходы списаны, силы восстановлены.');});$('#recover').onclick=()=>run(()=>E.recover(state));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>run(()=>{E.act(state,b.dataset.action);toast('Действие выполнено. Результат записан в журнал.');}));}document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>run(()=>{E.buy(state,b.dataset.buy);toast('Куплено! Эффект уже действует, предмет установлен в офисе.');}));if($('#acquire'))$('#acquire').onclick=()=>run(()=>{E.acquire(state,$('#company-name').value);toast('Компания теперь твоя. Найм и контракты открыты.');});if($('#expand'))$('#expand').onclick=()=>run(()=>E.expand(state));if($('#contract'))$('#contract').onclick=contractDialog;if($('#advance'))$('#advance').onclick=()=>{open('<h2>Аванс для выплаты зарплат</h2><p>Если денег не хватает на расходы дня, можно получить 300 CR. Цена: −10 репутации и −100 очков. Это спасает от остановки игры, но снижает результат.</p><button id="take-advance" class="btn">Получить аванс на этих условиях</button>');$('#take-advance').onclick=()=>run(()=>{E.advance(state);modal.close();});};document.querySelectorAll('[data-hire]').forEach(b=>b.onclick=()=>run(()=>{E.hire(state,b.dataset.hire);toast('Сотрудник принят. Зарплата добавлена к расходам дня.');}));}
function questionDialog(q,title,answer){open(`<span class="kicker">${title}</span><h2>${esc(q.prompt)}</h2><p>Выбери решение. После ответа получишь объяснение.</p><div class="options">${q.options.map((x,i)=>`<button class="option" data-dialog-answer="${i}"><span>${i+1}</span>${esc(x)}</button>`).join('')}</div>`);content.querySelectorAll('[data-dialog-answer]').forEach(b=>b.onclick=()=>{try{const result=answer(+b.dataset.dialogAnswer);save();render();open(`<h2>${result.correct?'Решение принято.':'Есть что исправить.'}</h2>${feedback(result)}${result.correct?`<div class="reward">${result.reward?'+'+result.reward+' CR':''} ${result.xp?'· +'+result.xp+' XP':''}</div>`:'<p>Можно попробовать снова. При нехватке фокуса используй перерыв или внеплановую паузу.</p>'}${result.promoted?`<div class="notice">Повышение: теперь ты ${result.promoted}!</div>`:''}<button class="btn" id="review-close">Вернуться к работе →</button>`);$('#review-close').onclick=()=>modal.close();}catch(e){toast(e.message);}});}
function taskDialog(){if(state.focus<12){toast('Нужно 12 фокуса. Сначала сделай перерыв.');return;}open(`<h2>${jobs[state.role].title}</h2><div id="career-puzzle"></div>`);practicalCleanup?.();practicalCleanup=mountPuzzle($('#career-puzzle'),state.role,()=>{try{const result=E.completePracticalTask(state);save();render();const done=document.createElement('div');done.className='reward';done.textContent=`Работа принята: +${result.reward} CR · +${result.xp} XP${result.promoted?' · Повышение: '+result.promoted:''}`;content.append(done);}catch(e){toast(e.message);}},{seed:state.day});}
function contractDialog(){open(`<h2>Контракт: ${jobs[state.role].title.toLowerCase()}</h2><div id="career-puzzle"></div>`);practicalCleanup?.();practicalCleanup=mountPuzzle($('#career-puzzle'),state.role,()=>{try{const result=E.completePracticalContract(state);save();render();const done=document.createElement('div');done.className='reward';done.textContent=`Контракт принят: +${result.reward} CR`;content.append(done);}catch(e){toast(e.message);}},{seed:state.company.contracts});}
function eventDialog(){const e=E.EVENTS[state.pending];if(!e)return;open(`<span class="kicker">СОБЫТИЕ / AI DIRECTOR</span><h2>${e.title}</h2><p>${e.text}</p><div class="options">${e.options.map((o,i)=>`<button class="option" data-event="${i}"><div>${o.text}<p class="mini">${o.hint}</p></div></button>`).join('')}</div>`,true);content.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>run(()=>{E.chooseEvent(state,+b.dataset.event);modal.close();}));}
function help(){open('<h2>Как пройти путь в IT</h2><p><b>1. Три профессии.</b> Белый хакер захватывает узлы учебной сети и контролирует обнаружение. Разработчик воспроизводит ошибки в приложении кафе, исправляет поведение, проверяет и выпускает обновление. Сисадмин восстанавливает связь, перезапускает серверы и устанавливает SSD с RAM в трёх комнатах.</p><p><b>Серверная.</b> WASD — движение, мышь — обзор, E — взять или подключить кабель. Если свободный обзор недоступен, зажми мышь и потяни или используй стрелки. R возвращает кабель, Esc ставит миссию на паузу.</p><p><b>2. Финальный запуск.</b> Три практических задания за шесть минут активной игры. Можно повторить.</p><p><b>3. Карьера.</b> Выполняй задачу дня и выбирай до двух дополнительных действий. Магазин помогает работать эффективнее.</p><p><b>4. Компания.</b> Достигни 1 050 XP и накопи 3 800 CR. После выкупа нанимай людей, выполняй контракты, расширяй офис и учитывай зарплаты.</p><p><b>Цель главы:</b> компания, офис на шесть мест, шесть сотрудников, три контракта. Все суммы игровые. Рейтинг локальный с NPC.</p>');}
function download(){if(!state)return;const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='devlife-v2-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function newGame(){open('<h2>Начать новый маршрут?</h2><p>Сначала можно скачать текущий прогресс. Автосохранение заменится только после выбора новой профессии. Старый прогресс версии 1 не затрагивается.</p><div class="row"><button class="btn secondary" id="download-old">Скачать прогресс</button><button class="btn" id="go-home">К выбору профессии</button></div>');$('#download-old').onclick=download;$('#go-home').onclick=()=>{location.href='./';};}
$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('Файл слишком большой');state=E.restore(await f.text());save();modal.close();render();toast('Прогресс восстановлен.');}catch(e){toast(e.message);}finally{$('#import').value='';}};
let previous=performance.now(),seconds=0;setInterval(()=>{const now=performance.now(),dt=(now-previous)/1000;previous=now;if(!state||document.hidden)return;if(state.stage==='boss'){E.tickBoss(state,dt);if(state.stage==='bossFailed')render();else if($('#boss-time')){$('#boss-time').textContent=Math.ceil(state.bossRemaining);$('#boss-time').classList.toggle('timer-low',state.bossRemaining<20);}}else if(state.stage==='career'&&!paused&&!modal.open){E.tickWorld(state,dt);if(state.pending)eventDialog();}seconds++;if(seconds%5===0)save();},1000);
window.addEventListener('pagehide',save);if(new URLSearchParams(location.search).has('resume')){try{const saved=localStorage.getItem(key);if(saved){const old=JSON.parse(saved);if(['backend','qa'].includes(old.role)&&!localStorage.getItem('devlife-before-three-careers'))localStorage.setItem('devlife-before-three-careers',saved);state=E.restore(saved);}}catch{}}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
